const START = new Date(2026,3,13);
const END = new Date(2026,8,13);
const months = ['Січень','Лютий','Березень','Квітень','Травень','Червень','Липень','Серпень','Вересень','Жовтень','Листопад','Грудень'];
const monthGen = ['січня','лютого','березня','квітня','травня','червня','липня','серпня','вересня','жовтня','листопада','грудня'];
let currentMonth = new Date(2026,7,1);
let selectedKey = null;
let pendingPhotos = [];
let viewerIndex = 0;
let selectedWeather = '';
const STORAGE = 'praktikum_diary_2026_v1';
const LOCKED_DATA = {...LOCKED_DATA_PART1, ...LOCKED_DATA_PART2};
const LOCKED_KEYS = new Set(Object.keys(LOCKED_DATA));

function loadData(){ try{ const saved=JSON.parse(localStorage.getItem(STORAGE)||'{}'); return {...saved,...LOCKED_DATA}; }catch(e){return {...LOCKED_DATA}} }
function saveData(data){ const merged={...data,...LOCKED_DATA}; localStorage.setItem(STORAGE,JSON.stringify(merged)) }
function keyOf(d){const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),dd=String(d.getDate()).padStart(2,'0');return y+'-'+m+'-'+dd}
function inRange(d){return d>=START && d<=END}
function showView(id){
  document.querySelectorAll('.view').forEach(el=>el.classList.remove('active'));
  const target=document.getElementById(id); if(target) target.classList.add('active');
  if(id==='calendarView') renderCalendar();
  if(id==='homeView'){updateCount();}
  loadInfoIntoFields();
  applyLangToActiveView();
}
function showCalendar(){showView('calendarView')}
function showHome(){showView('homeView')}
function changeMonth(delta){currentMonth.setMonth(currentMonth.getMonth()+delta);renderCalendar();applyLangToActiveView()}
function renderCalendar(){
  const y=currentMonth.getFullYear(), m=currentMonth.getMonth();
  document.getElementById('monthTitle').textContent=months[m]+' '+y;
  const days=document.getElementById('days'); days.innerHTML='';
  const first=new Date(y,m,1); let monday=(first.getDay()+6)%7;
  for(let i=0;i<monday;i++){const e=document.createElement('div');e.className='day empty';days.appendChild(e)}
  const count=new Date(y,m+1,0).getDate(), data=loadData();
  for(let n=1;n<=count;n++){
    const d=new Date(y,m,n), k=keyOf(d), item=data[k];
    const el=document.createElement('button'); el.type='button'; el.className='day';
    if(!inRange(d)){
      el.classList.add('outside');
      el.disabled=true;
      el.setAttribute('aria-disabled','true');
    } else {
      el.classList.add('in-germany');
    }
    if(d.getDay()===0) el.classList.add('sunday');
    if(k===keyOf(new Date())) el.classList.add('today');
    const hasPhoto=item?.photos?.length || item?.photo;
    const hasWeather=item?.weather && (item.weather.temp!=='' || item.weather.icon);
    if(hasPhoto) el.classList.add('has-photo');
    el.innerHTML='<span class="num">'+n+'</span>'+(item?.text||hasPhoto||hasWeather?'<span class="dot"></span>':'')+
      (item?.text?'<div class="preview">'+escapeHtml(item.text)+'</div>':'')+
      (hasWeather?'<div class="weather-cell">'+escapeHtml(item.weather.icon||'')+' '+(item.weather.temp!==''?escapeHtml(String(item.weather.temp))+'°C':'')+'</div>':'');
    el.dataset.date=k;
    el.onclick=function(e){
      e.preventDefault();
      e.stopImmediatePropagation();
      openDay(new Date(y,m,n));
      return false;
    };
    days.appendChild(el);
  }
  renderWeatherStats();
  if(typeof currentLang!=='undefined' && currentLang==='de' && typeof translateDynamicFields==='function') setTimeout(()=>translateDynamicFields(document),0);
}
function renderWeatherStats(){
  const box=document.getElementById('weatherStats'); if(!box)return;
  const data=loadData();
  const rows=Object.entries(data).filter(([k,v])=>inRange(new Date(k+'T00:00:00')) && v?.weather && v.weather.temp!=='' && v.weather.temp!=null);
  const temps=rows.map(([,v])=>{const m=String(v.weather.temp).match(/-?\d+(?:[.,]\d+)?/);return m?Number(m[0].replace(',','.')):null}).filter(Number.isFinite);
  if(!temps.length){box.innerHTML='';return;}
  const avg=temps.reduce((a,b)=>a+b,0)/temps.length, min=Math.min(...temps), max=Math.max(...temps);
  const icons={}; rows.forEach(([,v])=>{const icon=v.weather.icon||'•';icons[icon]=(icons[icon]||0)+1;});
  const mm={}; rows.forEach(([k,v])=>{const d=new Date(k+'T00:00:00'), n=String(v.weather.temp).match(/-?\d+(?:[.,]\d+)?/);if(n)(mm[d.getMonth()]??=[]).push(Number(n[0].replace(',','.')))});
  const names=['Січ','Лют','Бер','Квіт','Трав','Черв','Лип','Серп','Вер','Жовт','Лист','Груд'];
  const monthly=Object.entries(mm).map(([m,a])=>({m:+m,avg:a.reduce((x,y)=>x+y,0)/a.length})).sort((a,b)=>a.m-b.m);
  const scale=Math.max(...monthly.map(x=>Math.abs(x.avg)),1);
  const curMonth=new Date().getMonth();
  const labels={'☀️':'☀️ Сонячно','🌤️':'🌤️ Мінлива хмарність','☁️':'☁️ Хмарно','🌧️':'🌧️ Дощ','🌨️':'🌨️ Сніг','🌫️':'🌫️ Туман'};
  box.innerHTML=`<div class="weather-stats-head"><div><div class="weather-stats-title">Статистика погоди</div><div class="weather-stats-sub">За всіма заповненими днями практики</div></div><div class="weather-stats-sub">Середня температура</div></div><div class="weather-metrics"><div class="weather-metric"><div class="v">${temps.length}</div><div class="l">днів</div></div><div class="weather-metric"><div class="v">${avg.toFixed(1)}°</div><div class="l">середня</div></div><div class="weather-metric"><div class="v">${min}°</div><div class="l">мінімум</div></div><div class="weather-metric"><div class="v">${max}°</div><div class="l">максимум</div></div></div><div class="weather-chart" id="weatherChartRow">${monthly.map(x=>`<div class="weather-bar-wrap${x.m===curMonth?' is-current':''}"><div class="weather-bar-temp">${x.avg.toFixed(1)}°</div><div class="weather-bar" style="height:0px" data-h="${Math.max(8,Math.abs(x.avg)/scale*112)}"></div><div class="weather-bar-label">${names[x.m]}</div></div>`).join('')}</div><div class="weather-legend">${Object.entries(icons).sort((a,b)=>b[1]-a[1]).map(([i,n])=>`<span>${escapeHtml(labels[i]||i)} · ${n}</span>`).join('')}</div>`;
  const chartRow=document.getElementById('weatherChartRow');
  if(chartRow){
    requestAnimationFrame(()=>{
      chartRow.classList.add('animate');
      chartRow.querySelectorAll('.weather-bar').forEach(b=>{ b.style.height=b.dataset.h+'px'; });
      chartRow.scrollTo({left:chartRow.scrollWidth,behavior:'smooth'});
    });
  }
}
function escapeHtml(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
function getItemPhotos(item){
  if(!item) return [];
  if(item.photos) return item.photos.slice();
  if(item.photo) return [item.photo];
  return [];
}
function openDay(d){
  if(!inRange(d)) return;
  selectedKey=keyOf(d);
  const data=loadData(), item=data[selectedKey]||{}, locked=LOCKED_KEYS.has(selectedKey);
  pendingPhotos=getItemPhotos(item);
  document.getElementById('sheetTitle').textContent=d.getDate()+' '+monthGen[d.getMonth()]+' '+d.getFullYear();
  const textEl=document.getElementById('dayText'), tempEl=document.getElementById('weatherTemp');
  textEl.value=item.text||'';
  tempEl.value=item.weather?.temp ?? '';
  selectedWeather=item.weather?.icon||'';
  document.querySelectorAll('.weather-choice').forEach(b=>b.classList.toggle('selected',b.dataset.weather===selectedWeather));
  const modal=document.getElementById('modal'), sheet=modal.querySelector('.sheet');
  sheet.classList.toggle('locked-field',locked);
  textEl.readOnly=locked; tempEl.readOnly=locked;
  document.querySelectorAll('.weather-choice').forEach(b=>b.disabled=locked);
  const actions=sheet.querySelector('.actions');
  actions.style.display=locked?'none':'flex';
  renderPhotoGrid();
  let note=sheet.querySelector('.locked-note');
  if(locked){
    if(!note){ note=document.createElement('div'); note.className='locked-note'; sheet.appendChild(note); }
    note.textContent='🔒 ';
  } else if(note) note.remove();
  updateDayNav(d);
  document.getElementById('modal').classList.add('open');
}
function updateDayNav(d){
  const prev=new Date(d); prev.setDate(prev.getDate()-1);
  const next=new Date(d); next.setDate(next.getDate()+1);
  const pb=document.getElementById('prevDayBtn'), nb=document.getElementById('nextDayBtn');
  if(pb) pb.disabled=!inRange(prev);
  if(nb) nb.disabled=!inRange(next);
}
function saveCurrentDaySilently(){
  if(!selectedKey || LOCKED_KEYS.has(selectedKey)) return;
  const text=document.getElementById('dayText').value.trim(), data=loadData();
  const temp=document.getElementById('weatherTemp').value.trim();
  const item={};
  if(text)item.text=text;
  if(pendingPhotos.length)item.photos=pendingPhotos.slice();
  if(temp!=='' || selectedWeather) item.weather={temp:temp,icon:selectedWeather};
  if(Object.keys(item).length)data[selectedKey]=item; else delete data[selectedKey];
  saveData(data);
}
function navigateDay(delta){
  if(!selectedKey) return;
  saveCurrentDaySilently();
  const [y,m,dd]=selectedKey.split('-').map(Number);
  const d=new Date(y,m-1,dd);
  d.setDate(d.getDate()+delta);
  if(!inRange(d)) return;
  currentMonth=new Date(d.getFullYear(),d.getMonth(),1);
  renderCalendar();
  openDay(d);
}
function selectWeather(icon){selectedWeather=selectedWeather===icon?'':icon;document.querySelectorAll('.weather-choice').forEach(b=>b.classList.toggle('selected',b.dataset.weather===selectedWeather));}
function closeModal(){document.getElementById('modal').classList.remove('open')}
function renderPhotoGrid(){
  let grid=document.getElementById('photoGrid');
  if(!grid){
    grid=document.createElement('div');
    grid.id='photoGrid';
    grid.className='photo-grid calendar-photo-viewer';
    const textEl=document.getElementById('dayText');
    textEl.parentNode.insertBefore(grid, textEl.nextSibling);
  }
  grid.innerHTML='';
  if(!pendingPhotos.length){ grid.style.display='none'; return; }
  grid.style.display='grid';
  pendingPhotos.forEach((src,i)=>{
    const thumb=document.createElement('div'); thumb.className='photo-thumb';
    const img=document.createElement('img');
    img.className='book-hero-img'; img.src=src; img.alt='Фото '+(i+1);
    img.addEventListener('click',()=>openPhotoViewer(i));
    thumb.appendChild(img); grid.appendChild(thumb);
  });
}
function previewPhoto(e){}
function savePhotos(){}
function removePhotoAt(i){}
function deleteText(){
  if(LOCKED_KEYS.has(selectedKey)) return;
  const data=loadData(); if(!data[selectedKey]) return;
  delete data[selectedKey].text;
  if(!getItemPhotos(data[selectedKey]).length && !(data[selectedKey].weather?.temp!=='' || data[selectedKey].weather?.icon)) delete data[selectedKey];
  saveData(data); document.getElementById('dayText').value=''; renderCalendar(); updateCount(); showSaveToast();
}
function saveDay(){
  if(LOCKED_KEYS.has(selectedKey)) return;
  const text=document.getElementById('dayText').value.trim(), data=loadData();
  const temp=document.getElementById('weatherTemp').value.trim();
  const item={};
  if(text)item.text=text;
  if(pendingPhotos.length)item.photos=pendingPhotos.slice();
  if(temp!=='' || selectedWeather) item.weather={temp:temp,icon:selectedWeather};
  if(Object.keys(item).length)data[selectedKey]=item; else delete data[selectedKey];
  saveData(data); renderCalendar(); updateCount(); closeModal();
}

function showSaveToast(msg,isError){
  const t=document.getElementById('saveToast');
  document.getElementById('saveToastText').textContent=msg||'Збережено';
  document.getElementById('saveToastIcon').textContent=isError?'⚠':'✓';
  t.classList.toggle('toast-error',!!isError);
  t.classList.add('show');
  clearTimeout(window.__toastTimer);
  window.__toastTimer=setTimeout(()=>t.classList.remove('show'),isError?3200:1800);
}
function openPhotoViewer(i){
  if(!pendingPhotos.length) return;
  viewerIndex=i||0;
  renderViewer();
  document.getElementById('photoViewer').classList.add('open');
}
function renderViewer(){
  document.getElementById('fullPhoto').src=pendingPhotos[viewerIndex];
  document.getElementById('viewerCounter').textContent='Фото '+(viewerIndex+1)+' з '+pendingPhotos.length;
}
function viewerNav(delta){
  if(!pendingPhotos.length) return;
  viewerIndex=(viewerIndex+delta+pendingPhotos.length)%pendingPhotos.length;
  renderViewer();
}
function closePhotoViewer(){document.getElementById('photoViewer').classList.remove('open')}
const infoStorage = 'praktikum_sections_v1';
function loadInfoSections(){
  try{return JSON.parse(localStorage.getItem(infoStorage)||'{}')}catch(e){return{}}
}
function saveInfoSection(elementId,key){
  const data=loadInfoSections();
  data[key]=document.getElementById(elementId).value;
  localStorage.setItem(infoStorage,JSON.stringify(data));
  localStorage.setItem('plantsPresetVersion','v22-pdf');
  const s=document.getElementById(elementId+'Status');
  if(s){s.textContent='Збережено ✓'; setTimeout(()=>s.textContent='',1800)}
}

/* ===== Фото для «Мої поради і адаптація» =====
   Фото стискаються перед збереженням, щоб не забивати localStorage.
   Натискання на мініатюру відкриває вже наявний повноекранний переглядач.
*/
const advicePhotoStorage='praktikum_advice_photos_v1';
function loadAdvicePhotos(){
  try{return JSON.parse(localStorage.getItem(advicePhotoStorage)||'{}')}catch(e){return{}}
}
function saveAdvicePhotoData(data){
  try{
    localStorage.setItem(advicePhotoStorage,JSON.stringify(data));
    return true;
  }catch(e){
    showSaveToast('Не вдалося зберегти фото. Спробуй менше або менші фото.',true);
    return false;
  }
}
function resizeAdviceImage(file,maxSide=1400,quality=.78){
  return new Promise((resolve,reject)=>{
    const reader=new FileReader();
    reader.onload=()=>{
      const img=new Image();
      img.onload=()=>{
        const scale=Math.min(1,maxSide/Math.max(img.naturalWidth,img.naturalHeight));
        const w=Math.max(1,Math.round(img.naturalWidth*scale));
        const h=Math.max(1,Math.round(img.naturalHeight*scale));
        const canvas=document.createElement('canvas'); canvas.width=w; canvas.height=h;
        const ctx=canvas.getContext('2d'); ctx.drawImage(img,0,0,w,h);
        resolve(canvas.toDataURL('image/jpeg',quality));
      };
      img.onerror=reject; img.src=reader.result;
    };
    reader.onerror=reject; reader.readAsDataURL(file);
  });
}
async function addAdvicePhotos(key,files){
  const list=Array.from(files||[]).filter(f=>f.type.startsWith('image/'));
  if(!list.length)return;
  const data=loadAdvicePhotos();
  if(!Array.isArray(data[key]))data[key]=[];
  for(const file of list){
    try{
      const src=await resizeAdviceImage(file);
      data[key].push(src);
    }catch(e){console.error(e)}
  }
  if(saveAdvicePhotoData(data)){
    renderAdvicePhotos(key);
    showSaveToast('Фото збережено ✓');
    if(currentLang==='de')setTimeout(()=>translateDynamicFields(document),0);
  }
}
function renderAdvicePhotos(key){
  const box=document.getElementById(key+'Photos');
  const count=document.getElementById(key+'PhotoCount');
  if(!box)return;
  const photos=loadAdvicePhotos()[key]||[];
  box.innerHTML='';
  photos.forEach((src,index)=>{
    const item=document.createElement('div'); item.className='advice-photo-item';
    const img=document.createElement('img'); img.src=src; img.alt='Фото'; img.loading='lazy';
    img.onclick=()=>openLightbox(src);
    const rm=document.createElement('button'); rm.className='advice-photo-remove'; rm.type='button'; rm.textContent='×';
    rm.title='Видалити фото';
    rm.onclick=(e)=>{e.stopPropagation();removeAdvicePhoto(key,index)};
    item.append(img,rm); box.appendChild(item);
  });
  if(count)count.textContent=photos.length?`${photos.length} фото`:'';
}
function removeAdvicePhoto(key,index){
  const data=loadAdvicePhotos();
  if(!Array.isArray(data[key]))return;
  data[key].splice(index,1);
  saveAdvicePhotoData(data);
  renderAdvicePhotos(key);
}
function renderAllAdvicePhotos(){
  renderAdvicePhotos('adviceNotes');
  renderAdvicePhotos('adaptationNotes');
}




