function showMap(){showView('mapView')}
function selectMapZone(n){
  document.querySelectorAll('.map-building,.map-yard,.map-open').forEach(x=>x.classList.remove('selected'));
  const el=document.getElementById('zone'+n);
  if(el) el.classList.add('selected');
  const box=document.getElementById('mapSelected');
  const label=mapLabels[n] || 'Підпис нечитабельний на оригіналі';
  const labelOut=(typeof currentLang!=='undefined' && currentLang==='de' && typeof translateText==='function')?translateText(label):label;
  const note='Позначка №'+n+' на схемі господарства.';
  const noteOut=(typeof currentLang!=='undefined' && currentLang==='de' && typeof translateText==='function')?translateText(note):note;
  box.innerHTML='<strong>'+n+'. '+escapeHtml(labelOut)+'</strong><span>'+escapeHtml(noteOut)+'</span>';
}

function updateCount(){
  const data=loadData();
  document.getElementById('entryCount').textContent=Object.entries(data).filter(([k,x])=>inRange(new Date(k+'T00:00:00')) && (x.text||x.weather)).length;
}
updateCount();
renderCalendar();
loadInfoIntoFields();
renderAllAdvicePhotos();

let lightboxScale=1;
function openLightbox(src){
  const im=document.getElementById('lightboxImg');
  im.src=src; lightboxScale=1; im.style.transform='scale(1)';
  document.getElementById('lightbox').classList.add('open');
}
function zoomPhoto(delta){
  lightboxScale=Math.max(.5,Math.min(2.5,lightboxScale+delta));
  document.getElementById('lightboxImg').style.transform=`scale(${lightboxScale})`;
}
function fitPhoto(){
  lightboxScale=1;
  document.getElementById('lightboxImg').style.transform='scale(1)';
}
function closeLightbox(){document.getElementById('lightbox').classList.remove('open');}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeLightbox();});

