const PAIRS=Object.entries(OFFLINE_TRANSLATIONS).sort((a,b)=>b[0].length-a[0].length);

function translateText(text){
  let out=text;
  for(const [ua,de] of PAIRS) out=out.split(ua).join(de);
  return out;
}

function getTextNodes(root){
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{
    acceptNode(node){
      const p=node.parentElement;
      if(!p || p.closest('script,style,textarea,input,.no-translate')) return NodeFilter.FILTER_REJECT;
      return node.textContent && /[\p{L}]/u.test(node.textContent)
        ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_REJECT;
    }
  });
  const nodes=[]; let n;
  while(n=walker.nextNode()) nodes.push(n);
  return nodes;
}

function translateViewOffline(root){
  getTextNodes(root).forEach(node=>{
    if(!originalTextMap.has(node)) originalTextMap.set(node,node.nodeValue);
    node.nodeValue=translateText(originalTextMap.get(node));
  });
  document.querySelectorAll("[placeholder],[title],[aria-label]").forEach(el=>{
    ["placeholder","title","aria-label"].forEach(attr=>{
      if(!el.hasAttribute(attr)) return;
      let map=originalAttrMap.get(el);
      if(!map){map={};originalAttrMap.set(el,map);}
      if(map[attr]===undefined) map[attr]=el.getAttribute(attr);
      el.setAttribute(attr,translateText(map[attr]));
    });
  });
  if(currentLang==='de' && typeof window.translateUntranslatedNodes==='function') setTimeout(()=>window.translateUntranslatedNodes(root),0);
}

function restoreUK(){
  getTextNodes(document.body).forEach(node=>{
    if(originalTextMap.has(node)) node.nodeValue=originalTextMap.get(node);
  });
  document.querySelectorAll("[placeholder],[title],[aria-label]").forEach(el=>{
    const map=originalAttrMap.get(el);
    if(!map) return;
    Object.keys(map).forEach(attr=>el.setAttribute(attr,map[attr]));
  });
}

function updateTranslateButton(){
  const btn=document.getElementById('langToggle');
  if(btn) btn.textContent=currentLang==='de'?'🌐 DE → UA':'🌐 UA → DE';
}

function applyCurrentLanguage(){
  if(currentLang==='de') translateViewOffline(document.body); else restoreUK();
  document.documentElement.lang=currentLang; updateTranslateButton();
}
function applyLangToActiveView(){applyCurrentLanguage();if(typeof translateDynamicFields==='function')translateDynamicFields(document);}


function showSaveToast(msg,error=false){
  const toast=document.querySelector('.save-toast');
  if(!toast){ console.warn(msg); return; }
  toast.classList.toggle('toast-error',!!error);
  const txt=toast.querySelector('.toast-text');
  if(txt) txt.textContent=msg;
  else toast.textContent=msg;
  toast.classList.add('show');
  setTimeout(()=>toast.classList.remove('show'),2600);
}

async function toggleTranslate(){
  if(translating) return;
  translating=true;
  const btn=document.getElementById('langToggle');
  if(btn) btn.classList.add('busy');
  try{
    currentLang=currentLang==='uk'?'de':'uk';
    localStorage.setItem('practiceLanguage',currentLang);
    applyCurrentLanguage();
    if(currentLang==='de') setTimeout(()=>{ if(typeof window.translateUntranslatedNodes==='function') window.translateUntranslatedNodes(document); if(typeof window.__translateDynamicFields==='function') window.__translateDynamicFields(document); },80);
  }finally{
    translating=false;
    if(btn) btn.classList.remove('busy');
  }
}

document.addEventListener('DOMContentLoaded',()=>{
  applyCurrentLanguage();
});

