    "дрова":"Brennholz","будинку":"Haus","будинок":"Haus","кімнаті":"Zimmer",
    "робочий одяг":"Arbeitskleidung","взуття":"Schuhe","магазин":"Geschäft",
    "ферма":"Bauernhof","ферми":"Bauernhöfe","готель":"Hotel","містом":"Stadt",
    "міста":"Stadt","озера":"See","батькам":"Eltern","родиною":"Familie","другом":"Freund",
    "подругою":"Freundin","колегою":"Kollegen","шефом":"Chef","шефинею":"Chefin",
    "батьком шефа":"Vater des Chefs","дідусем":"Großvater","бабусею":"Großmutter",
    "сніданок":"Frühstück","обід":"Mittagessen","вечеря":"Abendessen","погода":"Wetter",
